pub(crate) fn project_tests_bounds_report(printed: &str, written: &str) -> Bytes {
    let head = format!("bounds in {}: ", written);
    let mut report: String = String::from("");
    let mut inside = false;
    for line in printed.lines() {
        if inside {
            if !line.starts_with(' ') { break; }
            report.push_str(line);
            report.push_str("\n");
            continue;
        }
        if line.starts_with(&*head) {
            inside = true;
            let cut = nikaia_std::text::find_first(&line, &" - written without their check: ");
            if cut.is_some() {
                let at = match cut { Some(__nikaia_value) => __nikaia_value, None => continue };
                report.push_str(line.before(at.start));
            } else { report.push_str(line); }
            report.push_str("\n");
        }
    }
    report.as_bytes().copy_of()
}

pub(crate) fn project_tests_asserts_report(printed: &str, written: &str) -> Bytes {
    let head = format!("asserts in {}: ", written);
    let mut report: String = String::from("");
    let mut inside = false;
    for line in printed.lines() {
        if inside && !line.starts_with(' ') { break; }
        if inside || line.starts_with(&*head) {
            inside = true;
            report.push_str(line);
            report.push_str("\n");
        }
    }
    report.as_bytes().copy_of()
}

pub(crate) fn project_tests_sharing_report(printed: &str, written: &str) -> Bytes {
    let head = format!("--- {}", written);
    let units = printed.lines().any(|line| { line.starts_with("--- ") });
    let mut report: String = String::from("");
    let mut inside = !units;
    for line in printed.lines() {
        if line.starts_with("--- ") {
            inside = AsRef::<str>::as_ref(&(line)) == AsRef::<str>::as_ref(&(head));
            continue;
        }
        if inside && !line.starts_with("Checked ") {
            report.push_str(line);
            report.push_str("\n");
        }
    }
    report.as_bytes().copy_of()
}

pub(crate) fn project_tests_bounds_outcome(program: &ProgramTest, outcome: &ProjectTestsOutcome, report: &str, asserts: &str, sharing: &str) -> ProjectTestsOutcome {
    let written = format!("tests/{}.nika", program.name);
    let mut bounds: Vec<(String, Bytes, Bytes)> = vec![];
    match &program.bounds {
        None => { },
        Some(want) => { bounds.push((format!("{}.bounds", program.name), want.copy_of(), project_tests_bounds_report(report, &written))); },
    }
    match &program.asserts {
        None => { },
        Some(want) => { bounds.push((format!("{}.asserts", program.name), want.copy_of(), project_tests_asserts_report(asserts, &written))); },
    }
    match &program.sharing {
        None => { },
        Some(want) => { bounds.push((format!("{}.sharing", program.name), want.copy_of(), project_tests_sharing_report(sharing, &written))); },
    }
    let right = bounds.iter().all(|entry| { entry.1 == entry.2 });
    ProjectTestsOutcome { ended_well: outcome.ended_well, stopped: outcome.stopped, passed: outcome.passed && right, stdout: outcome.stdout.copy_of(), stderr: nikaia_std::block::Text::from(outcome.stderr.to_string()), files: outcome.files.copy_owned(), bounds }
}

pub(crate) fn project_tests_explain_bounds(outcome: &ProjectTestsOutcome) -> Result<(), nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    for (name, want, got) in outcome.bounds.iter() {
        if want != got {
            nikaia_std::io::println(format_args!("tests/{} (- expected, + reported):", name))?;
            nikaia_std::io::print(format_args!("{}", project_tests_difference(want, got)))?;
        }
    }
    Ok(())
}

pub fn is_refusal(text: &str) -> bool { (text.starts_with("error") || text.contains("\nerror")) && !does_not_compile(text) }

pub(crate) fn does_not_compile(text: &str) -> bool { text.contains("could not compile") || text.contains("error[NK1343]") }

pub(crate) fn named_by(output: &OutputTest) -> String {
    match output.stdout.is_some() {
        true => format!("{}.stdout", output.name),
        false => format!("{}.out/", output.name),
    }
}

pub(crate) fn project_tests_difference(expected: &[u8], produced: &[u8]) -> String {
    let want = match expected.text() {
        Ok(value) => value,
        Err(_error) => { return String::from("  the bytes differ, and they are not text\n"); },
    };
    let got = match produced.text() {
        Ok(value) => value,
        Err(_error) => { return String::from("  the bytes differ, and they are not text\n"); },
    };
    differing_lines(want, got)
}

pub(crate) fn project_tests_agree(outcomes: &[(String, ProjectTestsOutcome)]) -> bool { (nikaia_std::range::span(1, outcomes.len() as i64)).all(|at| { nikaia_std::index::get(&outcomes, nikaia_std::index::at(at - 1)).1 == nikaia_std::index::get(&outcomes, nikaia_std::index::at(at)).1 }) }

pub(crate) fn project_tests_verdict(label: &str, outcomes: &[(String, ProjectTestsOutcome)]) -> Result<bool, nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    let agree = project_tests_agree(outcomes);
    let passed = agree && (nikaia_std::range::span(0, outcomes.len() as i64)).all(|at| { nikaia_std::index::get(&outcomes, nikaia_std::index::at(at)).1.passed });
    let said = match (passed, agree) {
        (true, _) => "ok",
        (false, true) => "FAILED",
        (false, false) => "FAILED (the settings disagree)",
    };
    nikaia_std::io::println(format_args!("{} ... {}", label, said))?;
    Ok(passed)
}

pub(crate) fn project_tests_running(total: i64) -> Result<(), nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    let plural = match total == 1 {
        true => "",
        false => "s",
    };
    nikaia_std::io::println(format_args!("running {} test{}", total, plural))?;
    Ok(())
}

pub fn project_tests_result(total: i64, failed: i64) -> Result<i32, nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    let passed = total - failed;
    let said = match failed == 0 {
        true => "ok",
        false => "FAILED",
    };
    nikaia_std::io::println(format_args!("\ntest result: {}. {} passed; {} failed", said, passed, failed))?;
    Ok(match failed == 0 {
        true => 0,
        false => 1,
    })
}

pub(crate) fn project_tests_output_label(output: &OutputTest) -> String { format!("output \"{}\" (tests/{})", output.name, named_by(output)) }

pub(crate) fn project_tests_program_label(program: &ProgramTest) -> String { format!("program \"{}\" (tests/{}.nika)", program.name, program.name) }

pub(crate) fn project_tests_wrote(got: &[(String, Option<Bytes>)], want: &[(String, Bytes)], at: i64) -> bool {
    match &nikaia_std::index::get(&got, nikaia_std::index::at(at)).1 {
        None => false,
        Some(written) => *written == nikaia_std::index::get(&want, nikaia_std::index::at(at)).1,
    }
}

pub(crate) async fn project_tests_written(path: &std::path::Path) -> Option<Bytes> {
    match fs::read(path, &fs::Root::Anywhere).await {
        Ok(value) => Some(value),
        Err(_error) => { None },
    }
}

pub async fn project_tests_output_outcome(output: &OutputTest, own: &std::path::Path, code: i64, stdout: Bytes, stderr: String) -> ProjectTestsOutcome {
    let ended_well = code == 0;
    let stopped = project_tests_stopped(code);
    let files: Vec<(String, Option<Bytes>)> = nikaia_std::seq::then(output.files.iter(), async |file| { (nikaia_std::block::Text::from(file.0.to_string()), project_tests_written(&nikaia_std::fs::path::join(&(own), std::path::Path::new(&(file.0)))).await) }).collect().await;
    let printed_right = match &output.stdout {
        None => true,
        Some(want) => *want == stdout,
    };
    let ended_right = match &output.stops {
        None => ended_well && match &output.stderr {
            None => true,
            Some(want) => *want == stderr.as_bytes(),
        },
        Some(want) => stopped && *want == stderr.as_bytes(),
    };
    let wrote_right = (nikaia_std::range::span(0, output.files.len() as i64)).all(|at| { project_tests_wrote(&files, &output.files, at) });
    ProjectTestsOutcome { ended_well, stopped, passed: ended_right && printed_right && wrote_right, stdout, stderr, files, bounds: vec![] }
}

pub(crate) fn project_tests_stopped(code: i64) -> bool { code == 101 }

pub fn project_tests_block_outcome(code: i64, stdout: Bytes, stderr: String) -> ProjectTestsOutcome {
    let ended_well = code == 0;
    ProjectTestsOutcome { ended_well, stopped: project_tests_stopped(code), passed: ended_well, stdout, stderr, files: vec![], bounds: vec![] }
}

pub(crate) fn project_tests_refused_outcome(program: &ProgramTest, stderr: &str) -> ProjectTestsOutcome {
    let broken = !is_refusal(stderr);
    let shown = match broken {
        true => format!("the program does not compile (rustc failed, not a refusal):\n{}", stderr),
        false => nikaia_std::block::Text::from(stderr.to_string()),
    };
    let passed = !broken && program.stops.is_none() && match &program.stderr {
        None => false,
        Some(want) => *want == shown.as_bytes(),
    };
    ProjectTestsOutcome { ended_well: false, stopped: false, passed, stdout: Bytes(vec![]), stderr: shown, files: vec![], bounds: vec![] }
}

pub(crate) fn project_tests_ran_outcome(program: &ProgramTest, code: i64, stdout: Bytes, said: String) -> ProjectTestsOutcome {
    let ended_well = code == 0;
    let stopped = project_tests_stopped(code);
    let printed_right = match &program.stdout {
        None => true,
        Some(want) => *want == stdout,
    };
    let ended_right = match &program.stops {
        None => ended_well && match &program.stderr {
            None => true,
            Some(want) => !is_refusal(match want.text() {
                Ok(value) => value,
                Err(_error) => { "" },
            }) && *want == said.as_bytes(),
        },
        Some(want) => stopped && *want == said.as_bytes(),
    };
    ProjectTestsOutcome { ended_well, stopped, passed: ended_right && printed_right, stdout, stderr: said, files: vec![], bounds: vec![] }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ProjectTestsRefusal {
    Refused(String),
}

impl ProjectTestsRefusal {
    pub fn message(&self) -> String {
        match self {
            ProjectTestsRefusal::Refused(why) => nikaia_std::block::Text::from(why.to_string()),
        }
    }
}
impl std::fmt::Display for ProjectTestsRefusal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.message())
    }
}
impl std::error::Error for ProjectTestsRefusal {}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ProjectTestsRan {
    pub code: i64,
    pub stdout: Bytes,
    pub stderr: Bytes,
    pub timed_out: bool,
    pub capped: i64,
}

pub(crate) fn project_tests_time_limit() -> i64 {
    let given = nikaia_std::index::or(text::parse_i64(nikaia_std::index::or(env::var("NIKAIA_TEST_TIME_LIMIT"), || "".into()).trim()), || 0);
    match given > 0 {
        true => given,
        false => 300,
    }
}

pub(crate) fn project_tests_process_limit() -> i64 {
    let given = nikaia_std::index::or(text::parse_i64(nikaia_std::index::or(env::var("NIKAIA_TEST_PROCESS_LIMIT"), || "".into()).trim()), || 0);
    match given > 0 {
        true => given,
        false => 4096,
    }
}

pub(crate) fn project_tests_capped_outcome(cap: i64, stdout: Bytes, said: &str) -> ProjectTestsOutcome {
    let shown = format!("ran into its cap of {} processes and threads (NIKAIA_TEST_PROCESS_LIMIT): a fork or a thread past it was refused, and every process it started was ended\n{}", cap, said);
    ProjectTestsOutcome { ended_well: false, stopped: false, passed: false, stdout, stderr: shown, files: vec![], bounds: vec![] }
}

pub(crate) fn project_tests_build_time_limit() -> i64 {
    let given = text::parse_i64(nikaia_std::index::or(env::var("NIKAIA_TEST_BUILD_TIME_LIMIT"), || "".into()).trim());
    match given {
        None => project_tests_time_limit().saturating_mul(10),
        Some(seconds) => match seconds > 0 {
            true => seconds,
            false => 0,
        },
    }
}

pub(crate) fn project_tests_timed_out_outcome(limit: i64, stdout: Bytes, said: &str) -> ProjectTestsOutcome {
    let shown = format!("timed out after {} s\n{}", limit, said);
    ProjectTestsOutcome { ended_well: false, stopped: false, passed: false, stdout, stderr: shown, files: vec![], bounds: vec![] }
}

pub(crate) fn project_tests_build_timed_out_outcome(limit: i64, said: &str) -> ProjectTestsOutcome {
    let hint = "hint: a build that hangs often waits on a Cargo lock another cargo holds; check once with `ps -ef --forest | grep -B2 -E 'cargo (rustc|build) .*--target-dir'`, or raise NIKAIA_TEST_BUILD_TIME_LIMIT (0: no limit)";
    let shown = format!("build timed out after {} s\n{}\n{}", limit, hint, said);
    ProjectTestsOutcome { ended_well: false, stopped: false, passed: false, stdout: Bytes(vec![]), stderr: shown, files: vec![], bounds: vec![] }
}

pub trait ProjectTestsProgramHost {
    fn package_name(&self, root: &std::path::Path) -> Result<Option<String>, std::boxed::Box<dyn std::error::Error>>;
    fn compiler(&self, verb: &str, setting: &str, project: &std::path::Path, dir: &std::path::Path, own: &std::path::Path, stdin: &[u8], within: i64, processes: i64, main: &std::path::Path) -> Result<ProjectTestsRan, std::boxed::Box<dyn std::error::Error>>;
    fn explained(&self, args: &[String], entry: &std::path::Path, own: &std::path::Path, main: &std::path::Path) -> Result<Bytes, std::boxed::Box<dyn std::error::Error>>;
    fn built(&self, project: &std::path::Path, dir: &std::path::Path, own: &std::path::Path, stdin: &[u8], within: i64, processes: i64, main: &std::path::Path) -> Result<Option<ProjectTestsRan>, std::boxed::Box<dyn std::error::Error>>;
    fn batched(&self, setting: &str, project: &std::path::Path, own: &std::path::Path, list: &std::path::Path, within: i64, main: &std::path::Path) -> Result<ProjectTestsBatchBuilt, std::boxed::Box<dyn std::error::Error>>;
    fn ran_batched(&self, binary: &std::path::Path, name: &str, dir: &std::path::Path, own: &std::path::Path, stdin: &[u8], within: i64, processes: i64, main: &std::path::Path) -> Result<ProjectTestsRan, std::boxed::Box<dyn std::error::Error>>;
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ProjectTestsBatchBuilt {
    pub binary: Option<fs::Path>,
    pub timed_out: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ProjectTestsBatched {
    pub binary: fs::Path,
    pub entry: fs::Path,
}

pub fn project_tests_times_file(cache: &std::path::Path, root: &std::path::Path) -> fs::Path {
    let shown = format!("{}", nikaia_std::fs::path::display(&(project_members_canonical(root))));
    let name: String = shown.chars().map(|c| { if c.is_alphanumeric() { c } else { '-' } }).collect();
    nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(cache), std::path::Path::new(&("test-times")))), std::path::Path::new(&(name)))
}

pub fn project_tests_places(cache: &std::path::Path, root: &std::path::Path) -> fs::Path {
    let shown = format!("{}", nikaia_std::fs::path::display(&(project_members_canonical(root))));
    let tag: String = hash::sha256_hex(shown.as_bytes()).chars().take(16).collect();
    nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(cache), std::path::Path::new(&("test-places")))), std::path::Path::new(&(tag)))
}

pub(crate) async fn project_tests_times_read(file: &std::path::Path) -> collections::BTreeMap<String, i64> {
    let mut times: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    let bytes = nikaia_std::index::or(project_tests_written(file).await, || Bytes(vec![]).into());
    for line in bytes.text_lossy().lines() {
        match line.split_once("\t") {
            None => { },
            Some((name, ms)) => { match text::parse_i64(ms.trim()) {
                None => { },
                Some(given) => { times.insert(nikaia_std::block::Text::from(name.to_string()), given); },
            }; },
        }
    }
    times
}

pub async fn project_tests_order(programs: &[ProgramTest], file: &std::path::Path) -> Vec<i64> {
    let times = project_tests_times_read(file).await;
    let mut keyed: Vec<(i64, i64)> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    let mut k = 0;
    keyed.reserve(programs.iter().size_hint().0); for program in programs.iter() {
        let ms = nikaia_std::index::or(times.get(&program.name), || -1);
        keyed.push((if ms < 0 { i64::MIN } else { unsafe { nikaia_std::proven::neg::<i64>(ms) } }, k));
        k += 1;
    }
    keyed.sort();
    keyed.iter().map(|pair| { pair.1 }).collect::<Vec<_>>()
}

pub async fn project_tests_remember(file: &std::path::Path, ran: &[(String, i64)]) {
    let mut times = project_tests_times_read(file).await;
    for (name, ms) in ran.iter() {
        let ms = nikaia_std::num::value(ms);
        times.insert(nikaia_std::block::Text::from(name.to_string()), ms);
    }
    let text: String = nikaia_std::block::Text::from(times.iter().map(|pair| { format!("{}\t{}\n", pair.0, pair.1) }).collect::<Vec<_>>().join(""));
    match nikaia_std::fs::path::parent(&(file)) {
        None => { },
        Some(ref parent) => { match fs::create_dir(parent, &fs::Root::Anywhere, true) {
            Ok(_) => {},
            Err(_error) => { return; },
        }; },
    }
    match fs::write(file, &fs::Root::Anywhere, text, false, true).await {
        Ok(_) => {},
        Err(_error) => { return; },
    };
}

pub(crate) fn project_tests_batch_least() -> i64 { 8 }

pub(crate) fn project_tests_batch_carrier() -> &'static str { "grammar Carrier {\n    rule n -> ref Bytes = s:bytes(until(\";\")) -> { s }\n    entry rule top -> i64 = x:n \";\" -> { x.len() }\n}\n\nfn main() throws {\n    let r = Carrier::top(\"abc;\") catch { -1 }\n    println(f\"{r}\")\n}\n" }

pub async fn project_tests_batches<H: ProjectTestsProgramHost>(host: &H, programs: &[ProgramTest], root: &std::path::Path, setting: &str, own: &std::path::Path) -> Result<collections::BTreeMap<String, ProjectTestsBatched>, std::boxed::Box<dyn std::error::Error>> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut found: collections::BTreeMap<String, ProjectTestsBatched> = collections::BTreeMap::new();
    if env::var("NIKAIA_TEST_NO_BATCH").is_some() { return Ok(found); }
    let wanted: Vec<ProgramTest> = programs.iter().map(|program| { program.clone() }).collect::<Vec<_>>();
    if (wanted.len() as i64) < project_tests_batch_least() { return Ok(found); }
    let dependency: String = match host.package_name(root)? {
        None => String::from(""),
        Some(ref name) => {
            let at = nikaia_std::fs::path::display(&(project_members_canonical(root)));
            format!("\n[dependencies]\n{} = {{ path = {:?} }}\n", name, at)
        },
    };
    let manifest = format!("[package]\nname = \"program_test\"\nversion = \"0.1.0\"\n{}", dependency);
    let mut chunks: Vec<Vec<ProgramTest>> = nikaia_std::block::List::from_array_in([wanted], nikaia_std::block::Place::Block);
    let mut made: i64 = 0;
    while !chunks.is_empty() {
        let chunk = match chunks.pop() { Some(__nikaia_value) => __nikaia_value, None => break };
        let dir = nikaia_std::fs::path::join(&(own), std::path::Path::new(&(format!("batch-{}", made))));
        made = made + 1;
        fs::create_dir(&nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("project")))), std::path::Path::new(&("src"))), &fs::Root::Anywhere, true)?;
        fs::write(&nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("project")))), std::path::Path::new(&("nikaia.toml"))), &fs::Root::Anywhere, nikaia_std::block::Text::from(manifest.to_string()), false, true).await?;
        fs::write(&nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("project")))), std::path::Path::new(&("src")))), std::path::Path::new(&("main.nika"))), &fs::Root::Anywhere, project_tests_batch_carrier(), false, true).await?;
        let mut lines: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
        fs::create_dir(&nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("programs"))), &fs::Root::Anywhere, true)?;
        let programs = fs::Root::Dir(nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("programs"))));
        lines.reserve(chunk.iter().size_hint().0); for program in chunk.iter() {
            let at: fs::Path = std::path::PathBuf::from(nikaia_std::block::Text::from(program.name.to_string()));
            fs::create_dir(&nikaia_std::fs::path::join(&(at), std::path::Path::new(&("src"))), &programs, true)?;
            fs::write(&nikaia_std::fs::path::join(&(at), std::path::Path::new(&("nikaia.toml"))), &programs, nikaia_std::block::Text::from(manifest.to_string()), false, true).await?;
            let entry = nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("programs")))), &at)), std::path::Path::new(&("src")))), std::path::Path::new(&("main.nika")));
            let source = nikaia_std::fs::path::join(&(program.dir), std::path::Path::new(&(format!("{}.nika", program.name))));
            let text = match fs::read(std::path::Path::new(&(format!("{}.nika", program.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(program.dir)))).await {
                Ok(value) => value,
                Err(error) => { return Err(nikaia_std::error::raise(ProjectTestsRefusal::Refused(format!("copying {}: {}", nikaia_std::fs::path::display(&(source)), error)), &"project_tests_batches")) },
            };
            match fs::write(&nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(at), std::path::Path::new(&("src")))), std::path::Path::new(&("main.nika"))), &programs, text, false, true).await {
                Ok(_) => {},
                Err(error) => { return Err(nikaia_std::error::raise(ProjectTestsRefusal::Refused(format!("copying {}: {}", nikaia_std::fs::path::display(&(source)), error)), &"project_tests_batches")); },
            };
            lines.push(format!("{}\t{}\n", program.name, nikaia_std::fs::path::display(&(entry))));
        }
        let list = nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("batch.list")));
        fs::write(&list, &fs::Root::Anywhere, nikaia_std::block::Text::from(lines.join("")), false, true).await?;
        let main = nikaia_std::fs::path::join(&(nikaia_std::index::get(&chunk, 0).dir), std::path::Path::new(&(format!("{}.nika", unsafe { nikaia_std::proven::read(&chunk, (0) as usize) }.name))));
        let built = host.batched(setting, &nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("project"))), &dir, &list, project_tests_build_time_limit(), &main)?;
        if built.timed_out { continue; }
        match built.binary {
            None => {
                let said = match fs::read_to_string(&nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("batch.said"))), &fs::Root::Anywhere).await {
                    Ok(value) => value,
                    Err(_error) => { String::from("") },
                };
                let ranges = match fs::read_to_string(&nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("batch.modules"))), &fs::Root::Anywhere).await {
                    Ok(value) => value,
                    Err(_error) => { String::from("") },
                };
                let cited = project_batch_cited(&said, &ranges, "program_test");
                let rest: Vec<ProgramTest> = chunk.iter().filter(|&program| { !nikaia_std::list::contains(&cited, &program.name) }).map(|program| { program.clone() }).collect::<Vec<_>>();
                if !cited.is_empty() && (rest.len() as i64) < chunk.len() as i64 {
                    if (rest.len() as i64) >= project_tests_batch_least() { chunks.push(rest); }
                    continue;
                }
                if (chunk.len() as i64) >= unsafe { nikaia_std::proven::mul::<i64>(2, project_tests_batch_least()) } {
                    let half = chunk.len() as i64 / 2;
                    chunks.push(chunk.iter().take(nikaia_std::count::of(half)).map(|program| { program.clone() }).collect::<Vec<_>>());
                    chunks.push(chunk.iter().skip(nikaia_std::count::of(half)).map(|program| { program.clone() }).collect::<Vec<_>>());
                }
            },
            Some(ref binary) => {
                let included = __keep_frame.put(match fs::read_to_string(&nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("batch.included"))), &fs::Root::Anywhere).await {
                    Ok(value) => value,
                    Err(_error) => { String::from("") },
                });
                for name in included.lines() {
                    let entry = nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("programs")))), std::path::Path::new(&(name)))), std::path::Path::new(&("src")))), std::path::Path::new(&("main.nika")));
                    found.insert(nikaia_std::block::Text::from(name.to_string()), ProjectTestsBatched { binary: nikaia_std::fs::path::clone(&(binary)), entry });
                }
            },
        }
    }
    Ok(found)
}

pub(crate) async fn project_tests_starts_processes(program: &ProgramTest) -> bool {
    let text = match fs::read_to_string(std::path::Path::new(&(format!("{}.nika", program.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(program.dir)))).await {
        Ok(value) => value,
        Err(_error) => { return false; },
    };
    text.contains("process::")
}

pub async fn project_tests_warm_up<H: ProjectTestsProgramHost>(host: &H, programs: &[ProgramTest], setting: &str, own: &std::path::Path) -> Result<(), std::boxed::Box<dyn std::error::Error>> {
    let mut starts = false;
    for program in programs.iter() {
        if project_tests_starts_processes(program).await {
            starts = true;
            break;
        }
    }
    if !starts { return Ok(()); }
    let project = nikaia_std::fs::path::join(&(own), std::path::Path::new(&("project")));
    fs::create_dir(&nikaia_std::fs::path::join(&(project), std::path::Path::new(&("src"))), &fs::Root::Anywhere, true)?;
    fs::write(&nikaia_std::fs::path::join(&(project), std::path::Path::new(&("nikaia.toml"))), &fs::Root::Anywhere, "[package]\nname = \"warm_up\"\nversion = \"0.1.0\"\n", false, true).await?;
    fs::write(&nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(project), std::path::Path::new(&("src")))), std::path::Path::new(&("main.nika"))), &fs::Root::Anywhere, "fn main() {\n}\n", false, true).await?;
    let limit = project_tests_build_time_limit();
    let out = host.compiler("run", setting, &project, own, own, &Bytes(vec![]), limit, 0, &nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(project), std::path::Path::new(&("src")))), std::path::Path::new(&("main.nika"))))?;
    if out.timed_out { return Err(nikaia_std::error::raise(ProjectTestsRefusal::Refused(format!("the warm-up of the program std (#1955) timed out after {} s\n{}", limit, out.stderr.text_lossy())), &"project_tests_warm_up")); }
    if out.code != 0 { return Err(nikaia_std::error::raise(ProjectTestsRefusal::Refused(format!("the warm-up of the program std (#1955) failed, exit {}:\n{}", out.code, out.stderr.text_lossy())), &"project_tests_warm_up")); }
    Ok(())
}

pub(crate) fn project_tests_empty_but(dir: &std::path::Path, keep: &str) -> Result<(), nikaia_std::error::Thrown<ProjectTestsRefusal>> {
    let at = fs::Root::Dir(nikaia_std::fs::path::clone(&(dir)));
    let names = match fs::read_dir(std::path::Path::new(&(".")), &at) {
        Ok(value) => value,
        Err(_error) => { return Ok(()); },
    };
    for name in names.iter() {
        if nikaia_std::fs::path::text_of(&(name)) == keep { continue; }
        match fs::remove(name, &at, true) {
            Ok(_) => {},
            Err(error) => { return Err(nikaia_std::error::throwing(ProjectTestsRefusal::Refused(format!("emptying {}: {}", nikaia_std::fs::path::display(&(nikaia_std::fs::path::join(&(dir), name))), error)), &"project_tests_empty_but")); },
        };
    }
    Ok(())
}

pub(crate) fn project_tests_relocated(said: &[u8], entry: &std::path::Path, written: &str, root: &std::path::Path) -> String {
    let package = format!("{}/", nikaia_std::fs::path::display(&(project_members_canonical(root))));
    nikaia_std::search::replaced(nikaia_std::search::replaced(nikaia_std::block::Text::from(said.text_lossy().replace(&*nikaia_std::fs::path::display(&(entry)), &*written)), &nikaia_std::fs::path::display(&(project_members_canonical(entry))), &written), &package, &"")
}

pub(crate) fn project_tests_joined(first: &[u8], then: &[u8]) -> Bytes {
    let mut all: Vec<u8> = first.iter().copied().collect::<Vec<_>>();
    all.extend(then.iter().copied());
    Bytes(all)
}

pub(crate) async fn project_tests_prepared<H: ProjectTestsProgramHost>(host: &H, program: &ProgramTest, root: &std::path::Path, own: &std::path::Path) -> Result<fs::Path, std::boxed::Box<dyn std::error::Error>> {
    let project = nikaia_std::fs::path::join(&(own), std::path::Path::new(&("project")));
    project_tests_empty_but(own, "project")?;
    project_tests_empty_but(&project, "target")?;
    fs::create_dir(&nikaia_std::fs::path::join(&(project), std::path::Path::new(&("src"))), &fs::Root::Anywhere, true)?;
    let source = nikaia_std::fs::path::join(&(program.dir), std::path::Path::new(&(format!("{}.nika", program.name))));
    let entry = nikaia_std::fs::path::join(&(nikaia_std::fs::path::join(&(project), std::path::Path::new(&("src")))), std::path::Path::new(&("main.nika")));
    let text = match fs::read(std::path::Path::new(&(format!("{}.nika", program.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(program.dir)))).await {
        Ok(value) => value,
        Err(error) => { return Err(nikaia_std::error::raise(ProjectTestsRefusal::Refused(format!("copying {}: {}", nikaia_std::fs::path::display(&(source)), error)), &"project_tests_prepared")) },
    };
    match fs::write(&entry, &fs::Root::Anywhere, text, false, true).await {
        Ok(_) => {},
        Err(error) => { return Err(nikaia_std::error::raise(ProjectTestsRefusal::Refused(format!("copying {}: {}", nikaia_std::fs::path::display(&(source)), error)), &"project_tests_prepared")); },
    };
    let dependency: String = match host.package_name(root)? {
        None => String::from(""),
        Some(ref name) => {
            let at = nikaia_std::fs::path::display(&(project_members_canonical(root)));
            format!("\n[dependencies]\n{} = {{ path = {:?} }}\n", name, at)
        },
    };
    fs::write(&nikaia_std::fs::path::join(&(project), std::path::Path::new(&("nikaia.toml"))), &fs::Root::Anywhere, format!("[package]\nname = \"program_test\"\nversion = \"0.1.0\"\n{}", dependency), false, true).await?;
    Ok(entry)
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ProjectTestsReports {
    pub bounds: String,
    pub asserts: String,
    pub sharing: String,
}

pub async fn project_tests_reports<H: ProjectTestsProgramHost>(host: &H, program: &ProgramTest, root: &std::path::Path, own: &std::path::Path) -> Result<ProjectTestsReports, std::boxed::Box<dyn std::error::Error>> {
    let mut found = ProjectTestsReports { bounds: String::from(""), asserts: String::from(""), sharing: String::from("") };
    if program.bounds.is_none() && program.asserts.is_none() && program.sharing.is_none() { return Ok(found); }
    let entry = project_tests_prepared(host, program, root, own).await?;
    let written = format!("tests/{}.nika", program.name);
    let main = nikaia_std::fs::path::join(&(program.dir), std::path::Path::new(&(format!("{}.nika", program.name))));
    if program.bounds.is_some() { found.bounds = project_tests_relocated(&host.explained(&vec![String::from("--bounds")], &entry, own, &main)?, &entry, &written, root); }
    if program.asserts.is_some() { found.asserts = project_tests_relocated(&host.explained(&vec![String::from("--asserts")], &entry, own, &main)?, &entry, &written, root); }
    if program.sharing.is_some() { found.sharing = project_tests_relocated(&host.explained(&vec![String::from("--sharing")], &entry, own, &main)?, &entry, &written, root); }
    Ok(found)
}

pub async fn project_tests_program_test<H: ProjectTestsProgramHost>(host: &H, program: &ProgramTest, root: &std::path::Path, setting: &str, own: &std::path::Path, batched: Option<&ProjectTestsBatched>, reports: &ProjectTestsReports) -> Result<ProjectTestsOutcome, std::boxed::Box<dyn std::error::Error>> {
    let project = nikaia_std::fs::path::join(&(own), std::path::Path::new(&("project")));
    let entry = project_tests_prepared(host, program, root, own).await?;
    let written = format!("tests/{}.nika", program.name);
    let main = nikaia_std::fs::path::join(&(root), std::path::Path::new(&(written)));
    let limit = project_tests_time_limit();
    let processes = project_tests_process_limit();
    match batched {
        None => { },
        Some(batch) => {
            let out = host.ran_batched(&batch.binary, &program.name, root, own, &program.stdin, limit, processes, &main)?;
            if out.capped > 0 { return Ok(project_tests_capped_outcome(out.capped, out.stdout, &project_tests_relocated(&out.stderr, &batch.entry, &written, root))); }
            if out.timed_out { return Ok(project_tests_timed_out_outcome(limit, out.stdout, &project_tests_relocated(&out.stderr, &batch.entry, &written, root))); }
            let ran = project_tests_ran_outcome(program, out.code, out.stdout, project_tests_relocated(&out.stderr, &batch.entry, &written, root));
            let outcome = project_tests_bounds_outcome(program, &ran, &nikaia_std::block::Text::from(reports.bounds.to_string()), &nikaia_std::block::Text::from(reports.asserts.to_string()), &nikaia_std::block::Text::from(reports.sharing.to_string()));
            if outcome.passed && out.stderr.is_empty() { return Ok(outcome); }
            project_tests_empty_but(own, "project")?;
        },
    }
    let report = nikaia_std::block::Text::from(reports.bounds.to_string());
    let asserts = nikaia_std::block::Text::from(reports.asserts.to_string());
    let sharing = nikaia_std::block::Text::from(reports.sharing.to_string());
    let building = project_tests_build_time_limit();
    let built = host.compiler("build", setting, &project, own, own, &Bytes(vec![]), building, 0, &main)?;
    if built.timed_out { return Ok(project_tests_build_timed_out_outcome(building, &project_tests_relocated(&built.stderr, &entry, &written, root))); }
    if built.code != 0 {
        let refused = project_tests_refused_outcome(program, &project_tests_relocated(&built.stderr, &entry, &written, root));
        return Ok(project_tests_bounds_outcome(program, &refused, &report, &asserts, &sharing));
    }
    let ran = match host.built(&project, root, own, &program.stdin, limit, processes, &main)? {
        None => {
            let out = host.compiler("run", setting, &project, root, own, &program.stdin, limit, processes, &main)?;
            let said = out.stderr.copy_of();
            (out, said)
        },
        Some(out) => {
            let said = project_tests_joined(&built.stderr, &out.stderr);
            (out, said)
        },
    };
    let (out, said) = ran;
    if out.capped > 0 { return Ok(project_tests_capped_outcome(out.capped, out.stdout, &project_tests_relocated(&said, &entry, &written, root))); }
    if out.timed_out { return Ok(project_tests_timed_out_outcome(limit, out.stdout, &project_tests_relocated(&said, &entry, &written, root))); }
    let outcome = project_tests_ran_outcome(program, out.code, out.stdout, project_tests_relocated(&said, &entry, &written, root));
    Ok(project_tests_bounds_outcome(program, &outcome, &report, &asserts, &sharing))
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ProjectTestsBlessed {
    Unchanged,
    Written,
    Refused(String),
}

pub(crate) fn project_tests_blessed_line(label: &str, blessed: &ProjectTestsBlessed) -> Result<bool, nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    match blessed {
        ProjectTestsBlessed::Unchanged => { nikaia_std::io::println(format_args!("{} ... ok", label))?; },
        ProjectTestsBlessed::Written => { nikaia_std::io::println(format_args!("{} ... blessed", label))?; },
        ProjectTestsBlessed::Refused(why) => {
            nikaia_std::io::println(format_args!("{} ... FAILED ({}, so it is not blessed)", label, why))?;
            return Ok(false);
        },
    }
    Ok(true)
}

pub(crate) async fn project_tests_bless_program(program: &ProgramTest, outcomes: &[(String, ProjectTestsOutcome)], stderr: bool) -> Result<ProjectTestsBlessed, nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    if outcomes.is_empty() { return Ok(ProjectTestsBlessed::Unchanged); }
    if !project_tests_agree(outcomes) { return Ok(ProjectTestsBlessed::Refused(String::from("the settings disagree"))); }
    let first = &unsafe { nikaia_std::proven::read(&outcomes, (0) as usize) }.1;
    let refused = !first.ended_well && !first.stopped && is_refusal(&first.stderr);
    let stops = first.stopped && program.stops.is_some();
    if refused && program.stderr.is_none() && !stderr { return Ok(ProjectTestsBlessed::Refused(String::from("the program is refused, no .stderr expects it and --bless-stderr was not given"))); }
    if !first.ended_well && !refused && !stops && first.stderr.starts_with("the program does not compile") { return Ok(ProjectTestsBlessed::Refused(String::from("the program does not compile"))); }
    if !first.ended_well && !refused && !stops { return Ok(ProjectTestsBlessed::Refused(String::from("the program did not end successfully"))); }
    if !stops && program.stops.is_some() { return Ok(ProjectTestsBlessed::Refused(String::from("the program did not stop, as its .stops expects"))); }
    let new_stdout = !refused && program.stdout.is_none() && !first.stdout.is_empty();
    let new_stderr = stderr && !refused && !stops && program.stderr.is_none() && !first.stderr.is_empty();
    if first.passed && !new_stdout && !new_stderr { return Ok(ProjectTestsBlessed::Unchanged); }
    if !refused && (program.stdout.is_some() || new_stdout) { fs::write(std::path::Path::new(&(format!("{}.stdout", program.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(program.dir))), first.stdout.copy_of(), false, true).await?; }
    if stops { fs::write(std::path::Path::new(&(format!("{}.stops", program.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(program.dir))), nikaia_std::bytes::Bytes::from(first.stderr.as_bytes()), false, true).await?; } else if refused || program.stderr.is_some() || new_stderr { fs::write(std::path::Path::new(&(format!("{}.stderr", program.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(program.dir))), nikaia_std::bytes::Bytes::from(first.stderr.as_bytes()), false, true).await?; }
    for (name, _, got) in first.bounds.iter() { fs::write(std::path::Path::new(&(name)), &fs::Root::Dir(nikaia_std::fs::path::clone(&(program.dir))), got.copy_of(), false, true).await?; }
    Ok(ProjectTestsBlessed::Written)
}

pub(crate) fn project_tests_explain_said(want: &[u8], written: &[u8]) -> Result<(), nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    if want != written {
        nikaia_std::io::println(format_args!("standard error (- expected, + written):"))?;
        nikaia_std::io::print(format_args!("{}", project_tests_difference(want, written)))?;
    }
    Ok(())
}

pub(crate) fn project_tests_explain_output(output: &OutputTest, outcome: &ProjectTestsOutcome) -> Result<(), nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    match &output.stops {
        None => { if !outcome.ended_well { nikaia_std::io::println(format_args!("the program did not end successfully"))?; } },
        _ => { if !outcome.stopped { nikaia_std::io::println(format_args!("the program did not stop, as its .stops expects"))?; } },
    }
    match &output.stdout {
        None => { },
        Some(want) => {
            if *want != outcome.stdout {
                nikaia_std::io::println(format_args!("standard output (- expected, + printed):"))?;
                nikaia_std::io::print(format_args!("{}", project_tests_difference(want, &outcome.stdout)))?;
            }
        },
    }
    match &output.stops {
        None => {
            match &output.stderr {
                None => { },
                Some(want) => { project_tests_explain_said(want, &outcome.stderr.as_bytes())?; },
            }
        },
        Some(want) => { project_tests_explain_said(want, &outcome.stderr.as_bytes())?; },
    }
    for (wanted, written) in output.files.iter().zip(outcome.files.iter()) {
        let relative = &wanted.0;
        let want = &wanted.1;
        match written.1 {
            None => { nikaia_std::io::println(format_args!("{}: not written", relative))?; },
            Some(ref got) => {
                if got != want {
                    nikaia_std::io::println(format_args!("{} (- expected, + written):", relative))?;
                    nikaia_std::io::print(format_args!("{}", project_tests_difference(want, got)))?;
                }
            },
        }
    }
    Ok(())
}

pub(crate) async fn project_tests_bless(output: &OutputTest, outcomes: &[(String, ProjectTestsOutcome)]) -> Result<ProjectTestsBlessed, nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    if outcomes.is_empty() { return Ok(ProjectTestsBlessed::Unchanged); }
    if !project_tests_agree(outcomes) { return Ok(ProjectTestsBlessed::Refused(String::from("the settings disagree"))); }
    let first = &unsafe { nikaia_std::proven::read(&outcomes, (0) as usize) }.1;
    let stops = first.stopped && output.stops.is_some();
    if !first.ended_well && !stops { return Ok(ProjectTestsBlessed::Refused(String::from("the program did not end successfully"))); }
    if !stops && output.stops.is_some() { return Ok(ProjectTestsBlessed::Refused(String::from("the program did not stop, as its .stops expects"))); }
    if first.files.iter().any(|file| { file.1.is_none() }) { return Ok(ProjectTestsBlessed::Refused(String::from("a file its .out/ names was not written"))); }
    if first.passed { return Ok(ProjectTestsBlessed::Unchanged); }
    if output.stdout.is_some() { fs::write(std::path::Path::new(&(format!("{}.stdout", output.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(output.dir))), first.stdout.copy_of(), false, true).await?; }
    if stops { fs::write(std::path::Path::new(&(format!("{}.stops", output.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(output.dir))), nikaia_std::bytes::Bytes::from(first.stderr.as_bytes()), false, true).await?; } else if output.stderr.is_some() { fs::write(std::path::Path::new(&(format!("{}.stderr", output.name))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(output.dir))), nikaia_std::bytes::Bytes::from(first.stderr.as_bytes()), false, true).await?; }
    let out: fs::Path = std::path::PathBuf::from(format!("{}.out", output.name));
    for (relative, got) in first.files.iter() {
        fs::write(&nikaia_std::fs::path::join(&(out), std::path::Path::new(&(relative))), &fs::Root::Dir(nikaia_std::fs::path::clone(&(output.dir))), match got {
            None => Bytes(vec![]),
            Some(written) => written.copy_of(),
        }, false, true).await?;
    }
    Ok(ProjectTestsBlessed::Written)
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ProjectTestsFailed {
    pub label: String,
    pub outcomes: Vec<(String, ProjectTestsOutcome)>,
    pub output: Option<OutputTest>,
}

pub trait ProjectTestsHost {
    fn block_outcome(&self, binary: &std::path::Path, k: i64) -> Result<ProjectTestsOutcome, std::boxed::Box<dyn std::error::Error>>;
    fn output_outcome(&self, binary: &std::path::Path, output: &OutputTest) -> Result<ProjectTestsOutcome, std::boxed::Box<dyn std::error::Error>>;
    fn program_failures(&self, bless: bool, stderr: bool) -> Result<Vec<ProjectTestsFailed>, std::boxed::Box<dyn std::error::Error>>;
}

pub async fn project_tests_program_done(program: &ProgramTest, outcomes: Vec<(String, ProjectTestsOutcome)>, bless: bool, stderr: bool) -> Result<Option<ProjectTestsFailed>, nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    let label = project_tests_program_label(program);
    if bless {
        let blessed = project_tests_bless_program(program, &outcomes, stderr).await?;
        if !project_tests_blessed_line(&label, &blessed)? { return Ok(Some(ProjectTestsFailed { label, outcomes, output: None })); }
        return Ok(None);
    }
    if !project_tests_verdict(&label, &outcomes)? { return Ok(Some(ProjectTestsFailed { label, outcomes, output: None })); }
    Ok(None)
}

pub fn project_tests_report_failures(failed: &[ProjectTestsFailed]) -> Result<(), nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    if failed.is_empty() { return Ok(()); }
    nikaia_std::io::println(format_args!("\nfailures:"))?;
    for one in failed.iter() {
        nikaia_std::io::println(format_args!("\n--- {}", one.label))?;
        let agree = project_tests_agree(&one.outcomes);
        let shown = match agree {
            true => 1,
            false => one.outcomes.len() as i64,
        };
        for (setting, outcome) in nikaia_std::index::get(&one.outcomes, nikaia_std::index::at(0..shown)).iter() {
            if !agree { nikaia_std::io::println(format_args!("at user-parallelism = {}:", setting))?; }
            match &one.output {
                None => {
                    nikaia_std::io::print(format_args!("{}", outcome.stdout.text_lossy()))?;
                    project_tests_explain_bounds(outcome)?;
                },
                Some(output) => { project_tests_explain_output(output, outcome)?; },
            }
            for line in outcome.stderr.lines() { nikaia_std::io::eprintln(format_args!("{}", text::escape_control(&nikaia_std::block::Text::from(line.to_string()))))?; }
        }
        if !agree { project_tests_explain_settings(&one.outcomes)?; }
    }
    Ok(())
}

pub(crate) fn project_tests_explain_settings(outcomes: &[(String, ProjectTestsOutcome)]) -> Result<(), nikaia_std::error::Thrown<nikaia_std::io::IoError>> {
    let base = &nikaia_std::index::get(&outcomes, 0).1;
    let named = &unsafe { nikaia_std::proven::read(&outcomes, (0) as usize) }.0;
    for (setting, outcome) in nikaia_std::index::get(&outcomes, 1..).iter() {
        if outcome == base { continue; }
        nikaia_std::io::println(format_args!("the settings differ (- at user-parallelism = {}, + at user-parallelism = {}):", named, setting))?;
        if outcome.ended_well != base.ended_well || outcome.stopped != base.stopped {
            nikaia_std::io::println(format_args!("  - {}", project_tests_ending(base)))?;
            nikaia_std::io::println(format_args!("  + {}", project_tests_ending(outcome)))?;
        }
        if outcome.passed != base.passed {
            nikaia_std::io::println(format_args!("  - {}", project_tests_passing(base)))?;
            nikaia_std::io::println(format_args!("  + {}", project_tests_passing(outcome)))?;
        }
        if outcome.stdout != base.stdout {
            nikaia_std::io::println(format_args!("standard output:"))?;
            nikaia_std::io::print(format_args!("{}", project_tests_difference(&base.stdout, &outcome.stdout)))?;
        }
        if outcome.stderr != base.stderr {
            nikaia_std::io::println(format_args!("standard error:"))?;
            for line in differing_lines(&base.stderr, &outcome.stderr).lines() { nikaia_std::io::println(format_args!("{}", text::escape_control(&nikaia_std::block::Text::from(line.to_string()))))?; }
        }
        for (want, got) in base.files.iter().zip(outcome.files.iter()) {
            if want.1 != got.1 {
                nikaia_std::io::println(format_args!("{}:", want.0))?;
                nikaia_std::io::print(format_args!("{}", project_tests_difference(&project_tests_or_none((want.1).as_deref()), &project_tests_or_none((got.1).as_deref()))))?;
            }
        }
        for (want, got) in base.bounds.iter().zip(outcome.bounds.iter()) {
            if want.2 != got.2 {
                nikaia_std::io::println(format_args!("tests/{}:", want.0))?;
                nikaia_std::io::print(format_args!("{}", project_tests_difference(&want.2, &got.2)))?;
            }
        }
    }
    Ok(())
}

pub(crate) fn project_tests_or_none(written: Option<&[u8]>) -> Bytes {
    match written {
        None => Bytes(vec![]),
        Some(bytes) => bytes.copy_of(),
    }
}

pub(crate) fn project_tests_ending(outcome: &ProjectTestsOutcome) -> &'static str {
    if outcome.ended_well { return "ended successfully"; }
    if outcome.stopped { return "stopped (exit 101)"; }
    "ended unsuccessfully"
}

pub(crate) fn project_tests_passing(outcome: &ProjectTestsOutcome) -> &'static str {
    match outcome.passed {
        true => "passed",
        false => "failed",
    }
}

#[allow(clippy::too_many_arguments)]
pub async fn project_tests_run<H: ProjectTestsHost>(host: &H, blocks: &[(String, fs::Path, i64, i64)], test_builds: &[(String, fs::Path)], outputs: &[OutputTest], programs: &[(String, fs::Path)], program_tests: i64, root: &std::path::Path, bless: bool, stderr: bool) -> Result<Vec<ProjectTestsFailed>, std::boxed::Box<dyn std::error::Error>> {
    let total = unsafe { nikaia_std::proven::add::<i64>(blocks.len() as i64, outputs.len() as i64) } + program_tests;
    project_tests_running(total)?;
    let mut failed: Vec<ProjectTestsFailed> = vec![];
    for (title, path, line, number) in blocks.iter() {
        let line = nikaia_std::num::value(line);let number = nikaia_std::num::value(number);
        let mut outcomes: Vec<(String, ProjectTestsOutcome)> = vec![];
        outcomes.reserve(test_builds.iter().size_hint().0); for (setting, binary) in test_builds.iter() { outcomes.push((nikaia_std::block::Text::from(setting.to_string()), host.block_outcome(binary, number)?)); }
        let label = format!("test \"{}\" ({}:{})", title, shown_path(path, root), line);
        if !project_tests_verdict(&label, &outcomes)? { failed.push(ProjectTestsFailed { label, outcomes, output: None }); }
    }
    for output in outputs.iter() {
        let mut outcomes: Vec<(String, ProjectTestsOutcome)> = vec![];
        outcomes.reserve(programs.iter().size_hint().0); for (setting, binary) in programs.iter() { outcomes.push((nikaia_std::block::Text::from(setting.to_string()), host.output_outcome(binary, output)?)); }
        let label = project_tests_output_label(output);
        if bless {
            let blessed = project_tests_bless(output, &outcomes).await?;
            if !project_tests_blessed_line(&label, &blessed)? { failed.push(ProjectTestsFailed { label, outcomes, output: Some(output.clone()) }); }
            continue;
        }
        if !project_tests_verdict(&label, &outcomes)? { failed.push(ProjectTestsFailed { label, outcomes, output: Some(output.clone()) }); }
    }
    for program in host.program_failures(bless, stderr)? { failed.push(program); }
    Ok(failed)
}

pub fn project_tests_wanted(name: &str, filters: &[String]) -> bool { filters.is_empty() || filters.iter().any(|text| { name.contains(AsRef::<str>::as_ref(text)) }) }

